# Builds the public site's index.html from second-listen.html, the one source file for both versions.
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$body = [IO.File]::ReadAllText("$root\second-listen.html")
$head = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0f0b0a"><meta name="description" content="Hear your classes again: transcripts, replay, a highlight reel and flashcards. Free, with your audio kept on your device."><link rel="canonical" href="https://abelmolinanj-dot.github.io/second-listen/"><meta property="og:type" content="website"><meta property="og:site_name" content="Second Listen"><meta property="og:title" content="Second Listen"><meta property="og:description" content="Hear your classes again: transcripts, replay, a highlight reel and flashcards. Free, with your audio kept on your device."><meta property="og:url" content="https://abelmolinanj-dot.github.io/second-listen/"><meta property="og:image" content="https://abelmolinanj-dot.github.io/second-listen/share.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="An eye with a spiral iris beside the words Second Listen."><meta name="twitter:card" content="summary_large_image"><link rel="manifest" href="manifest.webmanifest"><link rel="icon" href="icon-192.png"><link rel="apple-touch-icon" href="icon-192.png"><style>:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0}img{max-width:100%}[hidden]{display:none!important}</style></head><body>'
[IO.File]::WriteAllText("$root\index.html", $head + $body + '</body></html>', (New-Object Text.UTF8Encoding $false))
if (-not (Test-Path "$root\.nojekyll")) { [IO.File]::WriteAllText("$root\.nojekyll", "") }
"Built index.html"
